package main

import (
	"fmt"
	"log"
	"net"
	"net/dns"
	"sync"
)

func main() {
	// Create a new DNS server
	dnsServer := &dns.Server{
		Addr:    "localhost:53",
		Net:     "udp",
		Handler: &dnsHandler{},
	}

	// Start the DNS server
	if err := dnsServer.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}

type dnsHandler struct{}

func (h *dnsHandler) ServeDNS(w dns.ResponseWriter, r *dns.Msg) {
	// Create a new DNS request
	req := &dns.Msg{}
	req.SetQuestion(r.Question[0].Name, dns.TypeA)

	// Create a new DNS resolver
	resolver := &dns.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
			return net.Dial(network, address)
		},
	}

	// Resolve the hostname
	ips, err := resolver.Exchange(req, "8.8.8.8:53")
	if err != nil {
		log.Println(err)
		return
	}

	// Store the hostname to IP mapping
	h.hostnamesToIps.Store(r.Question[0].Name, ips.Answer[0].(*dns.A).Addr)

	// Create a new DNS response
	resp := &dns.Msg{}
	resp.SetReply(r)
	resp.Answer = append(resp.Answer, ips.Answer[0])

	// Write the response to the client
	if err := w.WriteMsg(resp); err != nil {
		log.Println(err)
		return
	}
}

type hostnamesToIps struct {
	mu    sync.Mutex
	store map[string]string
}

func (h *hostnamesToIps) Store(hostname string, ip string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.store[hostname] = ip
}

func (h *hostnamesToIps) Get(hostname string) (string, bool) {
	h.mu.Lock()
	defer h.mu.Unlock()
	ip, ok := h.store[hostname]
	return ip, ok
}
