```javascript
function packEntities(entities) {
    let buffer = new ArrayBuffer(4);
    let view = new DataView(buffer);
    let offset = 0;
    for (let entity of entities) {
        let id = entity.id;
        let size = entity.size;
        view.setUint8(offset, (id << 3) | size);
        offset++;
    }
    return buffer;
}

function unpackEntities(buffer) {
    let view = new DataView(buffer);
    let entities = [];
    for (let i = 0; i < buffer.byteLength; i++) {
        let id = (view.getUint8(i) >> 3) & 0x7;
        let size = view.getUint8(i) & 0x7;
        entities.push({ id, size });
    }
    return entities;
}
```

